/** A colour as your app stores it: a six-digit hex such as "#ff5b1f", and opacity from 0 to 1. */
export type ColorValue = { hex: string; alpha: number };

/** Hue in degrees (0–360); saturation and value (brightness) from 0 to 1. The picker works in this space. */
export type Hsv = { h: number; s: number; v: number };
export type Rgb = { r: number; g: number; b: number };
export type Hsl = { h: number; s: number; l: number };

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

/** Reads "#rgb", "#rrggbb" or the same without "#". Returns null for anything else. */
export function parseHex(text: string): string | null {
  const raw = text.trim().replace(/^#/, "").toLowerCase();
  if (/^[0-9a-f]{3}$/.test(raw)) return `#${[...raw].map((digit) => digit + digit).join("")}`;
  if (/^[0-9a-f]{6}$/.test(raw)) return `#${raw}`;
  return null;
}

export function hexToRgb(hex: string): Rgb {
  const value = parseHex(hex) ?? "#000000";
  return { r: parseInt(value.slice(1, 3), 16), g: parseInt(value.slice(3, 5), 16), b: parseInt(value.slice(5, 7), 16) };
}

export function rgbToHex({ r, g, b }: Rgb): string {
  return `#${[r, g, b].map((channel) => Math.round(clamp(channel, 0, 255)).toString(16).padStart(2, "0")).join("")}`;
}

export function rgbToHsv({ r, g, b }: Rgb): Hsv {
  const [red, green, blue] = [r / 255, g / 255, b / 255];
  const max = Math.max(red, green, blue);
  const delta = max - Math.min(red, green, blue);
  let h = 0;
  if (delta) {
    if (max === red) h = ((green - blue) / delta) % 6;
    else if (max === green) h = (blue - red) / delta + 2;
    else h = (red - green) / delta + 4;
  }
  return { h: (h * 60 + 360) % 360, s: max ? delta / max : 0, v: max };
}

export function hsvToRgb({ h, s, v }: Hsv): Rgb {
  const chroma = v * s;
  const x = chroma * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - chroma;
  const [red, green, blue] =
    h < 60 ? [chroma, x, 0] : h < 120 ? [x, chroma, 0] : h < 180 ? [0, chroma, x] : h < 240 ? [0, x, chroma] : h < 300 ? [x, 0, chroma] : [chroma, 0, x];
  return { r: (red + m) * 255, g: (green + m) * 255, b: (blue + m) * 255 };
}

export function rgbToHsl({ r, g, b }: Rgb): Hsl {
  const [red, green, blue] = [r / 255, g / 255, b / 255];
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const l = (max + min) / 2;
  const delta = max - min;
  const s = delta ? delta / (1 - Math.abs(2 * l - 1)) : 0;
  return { h: rgbToHsv({ r, g, b }).h, s, l };
}

export function hslToRgb({ h, s, l }: Hsl): Rgb {
  const chroma = (1 - Math.abs(2 * l - 1)) * s;
  const v = l + chroma / 2;
  return hsvToRgb({ h, s: v ? chroma / v : 0, v });
}

export const hsvToHex = (hsv: Hsv) => rgbToHex(hsvToRgb(hsv));
export const hexToHsv = (hex: string) => rgbToHsv(hexToRgb(hex));

/** Whether two colours are the same to the nearest whole channel and percent of opacity. */
export const sameColor = (a: ColorValue | null, b: ColorValue | null) =>
  a === b || (!!a && !!b && parseHex(a.hex) === parseHex(b.hex) && Math.round(a.alpha * 100) === Math.round(b.alpha * 100));

/** Black or white, whichever reads better on the colour, for marks drawn over it. */
export function contrastOn(hex: string) {
  const { r, g, b } = hexToRgb(hex);
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.6 ? "#000" : "#fff";
}

export { clamp };

"use client";

import { Popover } from "@base-ui/react/popover";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, forwardRef, useRef, useSyncExternalStore } from "react";
import { type Hsv, clamp, hexToHsv, hexToRgb, hslToRgb, hsvToHex, rgbToHsl, rgbToHsv } from "./color-picker-color";
import { ColorChip, ColorPickerAlphaInput, ColorPickerHexInput, ColorPickerNumberInput, checkerboard } from "./color-picker-inputs";
import { type ColorPickerFormat, useColorPicker } from "./color-picker-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(phoneQuery);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
/** Phones get a bottom sheet; the server renders the desktop popover, then adapts. */
const usePhone = () => useSyncExternalStore(subscribe, () => typeof window.matchMedia === "function" && window.matchMedia(phoneQuery).matches, () => false);

type ContentProps = ComponentPropsWithoutRef<"div"> & {
  /** "fixed" (the default) keeps the picker whole inside panels that clip or scroll; "absolute" scrolls with the page. */
  positionMethod?: "absolute" | "fixed";
  /** Which side of the row the picker opens on, such as "left" in an inspector on the right edge. */
  side?: "top" | "bottom" | "left" | "right";
  align?: "start" | "center" | "end";
  /** What the picker opens beside. Defaults to the picker's row, or the nearest box around it when the row is laid out as contents. */
  anchor?: Element | null;
};

/** The row, or its nearest ancestor with a box: a row with display: contents measures as nothing at the window's corner. */
const rowAnchor = (root: HTMLElement | null) => {
  let element: HTMLElement | null = root;
  while (element && getComputedStyle(element).display === "contents") element = element.parentElement;
  return element;
};

/**
 * The picker: a popover beside the whole row, so it never covers the colour being edited, or a bottom
 * sheet on phones. Without room on its side it flips, then moves to the other axis. Escape or clicking outside closes it.
 */
export const ColorPickerContent = forwardRef<HTMLDivElement, ContentProps>(function ColorPickerContent(
  { className, positionMethod = "fixed", side = "bottom", align = "start", anchor, children, ...props },
  ref,
) {
  const picker = useColorPicker();
  const phone = usePhone();
  return (
    <Popover.Portal container={picker.container ?? undefined}>
      <Popover.Positioner
        anchor={anchor ?? (() => rowAnchor(picker.rootRef.current))}
        side={side}
        align={align}
        sideOffset={6}
        collisionAvoidance={{ side: "flip", align: "shift", fallbackAxisSide: "end" }}
        positionMethod={positionMethod}
        className="z-50 outline-none"
        style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}
      >
        <Popover.Popup
          ref={ref}
          aria-label={picker.label}
          initialFocus={false}
          className={cn(
            // A deep, soft shadow, so the picker lifts off light and dark surfaces alike.
            "grid w-60 gap-3 rounded-lg border border-border bg-popover p-3 text-sm text-popover-foreground shadow-[0_16px_40px_-12px_rgb(0_0_0/0.45),0_4px_12px_-4px_rgb(0_0_0/0.25)] outline-none",
            phone && "w-full rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
            picker.animated &&
              (phone
                ? "transition-[transform,opacity] duration-200 ease-out data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full motion-reduce:transition-none"
                : "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none"),
            className,
          )}
          {...props}
        >
          {children}
        </Popover.Popup>
      </Popover.Positioner>
    </Popover.Portal>
  );
});

/** Tracks a press on an element as fractions of its width and height, until release. */
function usePointerTrack(onMove: (x: number, y: number) => void, onEnd: () => void) {
  const pressed = useRef<number | null>(null);
  const at = (event: PointerEvent<HTMLElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    onMove(clamp((event.clientX - rect.left) / (rect.width || 1), 0, 1), clamp((event.clientY - rect.top) / (rect.height || 1), 0, 1));
  };
  return {
    onPointerDown: (event: PointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      pressed.current = event.pointerId;
      try {
        event.currentTarget.setPointerCapture(event.pointerId);
      } catch {}
      event.currentTarget.focus();
      at(event);
    },
    onPointerMove: (event: PointerEvent<HTMLElement>) => pressed.current === event.pointerId && at(event),
    onPointerUp: (event: PointerEvent<HTMLElement>) => {
      if (pressed.current !== event.pointerId) return;
      pressed.current = null;
      onEnd();
    },
    onPointerCancel: () => {
      pressed.current = null;
      onEnd();
    },
  };
}

const thumb = "pointer-events-none absolute size-3.5 -translate-1/2 rounded-full border-2 border-white shadow-[0_0_0_1px_rgb(0_0_0/0.3),0_1px_3px_rgb(0_0_0/0.4)]";

/** Steps a value with the arrow keys: 1 at a time, or 10 with Shift; Home and End go to the ends. */
function stepKeys(event: KeyboardEvent, keys: { less: string[]; more: string[] }, apply: (delta: number | "min" | "max") => void) {
  const big = event.shiftKey ? 10 : 1;
  if (keys.less.includes(event.key)) apply(-big);
  else if (keys.more.includes(event.key)) apply(big);
  else if (event.key === "Home") apply("min");
  else if (event.key === "End") apply("max");
  else return;
  event.preventDefault();
}

/** Saturation left to right, brightness bottom to top. Drag to preview, release to commit; arrow keys step it. */
export const ColorPickerArea = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function ColorPickerArea({ className, ...props }, ref) {
  const picker = useColorPicker();
  const { hsv, alpha } = picker.color ?? picker.fallback;
  const track = usePointerTrack((x, y) => picker.preview({ hsv: { h: hsv.h, s: x, v: 1 - y }, alpha }), picker.release);
  const saturation = Math.round(hsv.s * 100);
  const brightness = Math.round(hsv.v * 100);
  return (
    <div
      ref={ref}
      role="slider"
      tabIndex={picker.disabled ? -1 : 0}
      aria-label={picker.messages.area}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={saturation}
      aria-valuetext={picker.messages.areaValue(saturation, brightness)}
      aria-disabled={picker.disabled || undefined}
      aria-readonly={picker.readOnly || undefined}
      className={cn("relative h-36 touch-none rounded-md outline-none select-none focus-visible:ring-1 focus-visible:ring-ring", picker.editable && "cursor-crosshair", className)}
      // White to the hue across, then fading to black downwards.
      style={{ background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, ${hsvToHex({ h: hsv.h, s: 1, v: 1 })})` }}
      {...(picker.editable ? track : {})}
      onKeyDown={(event) => {
        if (!picker.editable) return;
        stepKeys(event, { less: ["ArrowLeft"], more: ["ArrowRight"] }, (delta) => {
          const s = delta === "min" ? 0 : delta === "max" ? 1 : clamp(hsv.s + delta / 100, 0, 1);
          picker.commit({ hsv: { ...hsv, s }, alpha });
        });
        stepKeys(event, { less: ["ArrowDown"], more: ["ArrowUp"] }, (delta) => {
          if (delta === "min" || delta === "max") return;
          picker.commit({ hsv: { ...hsv, v: clamp(hsv.v + delta / 100, 0, 1) }, alpha });
        });
      }}
      {...props}
    >
      <span className={thumb} style={{ left: `${hsv.s * 100}%`, top: `${(1 - hsv.v) * 100}%`, background: hsvToHex(hsv) }} />
    </div>
  );
});

type SliderProps = ComponentPropsWithoutRef<"div"> & { channel: "hue" | "alpha" };

/** A horizontal hue or opacity slider. Drag to preview, release to commit; arrow keys step it. */
export const ColorPickerSlider = forwardRef<HTMLDivElement, SliderProps>(function ColorPickerSlider({ channel, className, ...props }, ref) {
  const picker = useColorPicker();
  const { hsv, alpha } = picker.color ?? picker.fallback;
  const hue = channel === "hue";
  const max = hue ? 360 : 100;
  const current = hue ? hsv.h : alpha * 100;
  const set = (next: number) => (hue ? { hsv: { ...hsv, h: clamp(next, 0, 359.99) }, alpha } : { hsv, alpha: clamp(next, 0, 100) / 100 });
  const track = usePointerTrack((x) => picker.preview(set(x * max)), picker.release);
  const solid = hsvToHex(hsv);
  return (
    <div
      ref={ref}
      role="slider"
      tabIndex={picker.disabled ? -1 : 0}
      aria-label={hue ? picker.messages.hue : picker.messages.opacity}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={Math.round(current)}
      aria-valuetext={hue ? `${Math.round(current)}°` : `${Math.round(current)}%`}
      aria-disabled={picker.disabled || undefined}
      aria-readonly={picker.readOnly || undefined}
      className={cn("relative h-3 touch-none rounded-full outline-none select-none focus-visible:ring-1 focus-visible:ring-ring", !hue && checkerboard, picker.editable && "cursor-pointer", className)}
      {...(picker.editable ? track : {})}
      onKeyDown={(event) => {
        if (!picker.editable) return;
        stepKeys(event, { less: ["ArrowLeft", "ArrowDown"], more: ["ArrowRight", "ArrowUp"] }, (delta) =>
          picker.commit(set(delta === "min" ? 0 : delta === "max" ? max : current + delta)),
        );
      }}
      {...props}
    >
      <span
        aria-hidden
        className="absolute inset-0 rounded-full"
        style={{ background: hue ? "linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)" : `linear-gradient(to right, transparent, ${solid})` }}
      />
      <span className={cn(thumb, "top-1/2")} style={{ left: `${(current / max) * 100}%`, background: hue ? hsvToHex({ h: hsv.h, s: 1, v: 1 }) : solid }} />
    </div>
  );
});

type EyeDropperWindow = { EyeDropper?: new () => { open: () => Promise<{ sRGBHex: string }> } };
const eyeDropperSupported = () => typeof window !== "undefined" && "EyeDropper" in window;

/** Picks a colour from anywhere on screen. Shown only in browsers with the EyeDropper API. */
export const ColorPickerEyeDropper = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button">>(function ColorPickerEyeDropper({ className, ...props }, ref) {
  const picker = useColorPicker();
  const supported = useSyncExternalStore(() => () => {}, eyeDropperSupported, () => false);
  if (!supported) return null;
  return (
    <button
      ref={ref}
      type="button"
      aria-label={picker.messages.eyedropper}
      title={picker.messages.eyedropper}
      disabled={!picker.editable}
      onClick={async () => {
        const Dropper = (window as unknown as EyeDropperWindow).EyeDropper;
        if (!Dropper) return;
        try {
          const { sRGBHex } = await new Dropper().open();
          picker.commit({ hsv: hexToHsv(sRGBHex), alpha: picker.alpha ?? 1 });
        } catch {
          // Cancelled with Escape: nothing changes.
        }
      }}
      className={cn(
        "grid size-8 shrink-0 place-items-center rounded-md border border-input text-muted-foreground shadow-xs outline-none hover:bg-accent hover:text-foreground focus-visible:border-ring focus-visible:text-foreground disabled:opacity-50",
        className,
      )}
      {...props}
    >
      <svg aria-hidden viewBox="0 0 16 16" className="size-4" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
        <path d="m9.5 4 2.5 2.5M3 13l1-3 5.75-5.75a1.77 1.77 0 0 1 2.5 2.5L6.5 12.5Z" />
      </svg>
    </button>
  );
});

const formats: ColorPickerFormat[] = ["hex", "rgb", "hsl"];

type SwitchProps = ComponentPropsWithoutRef<"div"> & {
  /** Class for the knob that slides to the chosen format. */
  highlightClassName?: string;
};

/**
 * Chooses the format the value shows, styled like Inspector Field's Off/On toggle: a muted track
 * with a raised knob that slides to the choice. Arrow keys move between formats; the chosen one is the single tab stop.
 */
export const ColorPickerFormatSwitch = forwardRef<HTMLDivElement, SwitchProps>(function ColorPickerFormatSwitch({ highlightClassName, className, onKeyDown, ...props }, ref) {
  const picker = useColorPicker();
  const index = formats.indexOf(picker.format);
  return (
    <div
      ref={ref}
      role="radiogroup"
      aria-label={picker.messages.format}
      className={cn("relative isolate grid h-8 grid-cols-3 rounded-md border border-input bg-muted p-0.5 text-sm dark:bg-input/40", className)}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        const step = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 0;
        if (event.defaultPrevented || !step) return;
        event.preventDefault();
        const next = formats[(index + step + formats.length) % formats.length];
        picker.setFormat(next);
        event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="radio"]')[formats.indexOf(next)]?.focus();
      }}
      {...props}
    >
      <span
        aria-hidden
        className={cn(
          "absolute inset-y-0.5 left-0.5 -z-10 w-[calc((100%-0.25rem)/3)] rounded-sm bg-background shadow-sm ring-1 ring-border",
          picker.animated && "transition-transform duration-200 ease-out motion-reduce:transition-none",
          highlightClassName,
        )}
        style={{ transform: `translateX(${index * 100}%)` }}
      />
      {formats.map((format) => (
        <button
          key={format}
          type="button"
          role="radio"
          aria-checked={picker.format === format}
          tabIndex={picker.format === format ? 0 : -1}
          onClick={() => picker.setFormat(format)}
          className="rounded-md text-muted-foreground outline-none select-none focus-visible:bg-foreground/10 focus-visible:text-foreground aria-checked:text-foreground"
        >
          {picker.messages.formats[format]}
        </button>
      ))}
    </div>
  );
});

/** The colour in the chosen format, with opacity. The app always receives hex and opacity. */
export const ColorPickerValue = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function ColorPickerValue({ className, ...props }, ref) {
  const picker = useColorPicker();
  const hsv: Hsv | null = picker.color?.hsv ?? null;
  const rgb = picker.hex ? hexToRgb(picker.hex) : null;
  const hsl = rgb ? rgbToHsl(rgb) : null;
  const alpha = picker.alpha ?? 1;
  const fromRgb = (next: Partial<{ r: number; g: number; b: number }>) => rgb && picker.commit({ hsv: rgbToHsv({ ...rgb, ...next }), alpha });
  const fromHsl = (next: Partial<{ h: number; s: number; l: number }>) => {
    if (!hsl || !hsv) return;
    const converted = rgbToHsv(hslToRgb({ ...hsl, ...next }));
    // Keep the chosen hue even when the colour is grey.
    picker.commit({ hsv: { ...converted, h: next.h ?? hsv.h }, alpha });
  };
  const channel = (key: keyof typeof picker.messages.channels, value: number | null, max: number, apply: (value: number) => void) => (
    <ColorPickerNumberInput aria-label={`${picker.label} ${picker.messages.channels[key]}`} value={value} min={0} max={max} onApply={apply} className="flex-1" />
  );
  return (
    <div
      ref={ref}
      className={cn("flex h-8 items-center gap-1 rounded-md border border-input px-1.5 focus-within:border-ring", className)}
      {...props}
    >
      {picker.format === "hex" && <ColorPickerHexInput id={`${picker.inputId}-popup`} className="flex-1" />}
      {picker.format === "rgb" && (
        <>
          {channel("r", rgb && Math.round(rgb.r), 255, (r) => fromRgb({ r }))}
          {channel("g", rgb && Math.round(rgb.g), 255, (g) => fromRgb({ g }))}
          {channel("b", rgb && Math.round(rgb.b), 255, (b) => fromRgb({ b }))}
        </>
      )}
      {picker.format === "hsl" && (
        <>
          {channel("h", hsv && Math.round(hsv.h), 360, (h) => fromHsl({ h: h % 360 }))}
          {channel("s", hsl && Math.round(hsl.s * 100), 100, (s) => fromHsl({ s: s / 100 }))}
          {channel("l", hsl && Math.round(hsl.l * 100), 100, (l) => fromHsl({ l: l / 100 }))}
        </>
      )}
      <span aria-hidden className="h-4 w-px shrink-0 bg-border" />
      <ColorPickerAlphaInput />
    </div>
  );
});

type FieldsProps = ComponentPropsWithoutRef<"div"> & {
  /** Class for the format switch. */
  formatClassName?: string;
  /** Class for the switch's sliding knob. */
  formatHighlightClassName?: string;
};

/** The format switch with the value below it, for pickers that keep them together. */
export const ColorPickerFields = forwardRef<HTMLDivElement, FieldsProps>(function ColorPickerFields({ formatClassName, formatHighlightClassName, className, ...props }, ref) {
  return (
    <div ref={ref} className={cn("grid gap-1.5", className)} {...props}>
      <ColorPickerFormatSwitch className={formatClassName} highlightClassName={formatHighlightClassName} />
      <ColorPickerValue />
    </div>
  );
});

/** Your app's swatches and the recently chosen colours. Choosing one commits it. */
export const ColorPickerSwatches = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function ColorPickerSwatches({ className, ...props }, ref) {
  const picker = useColorPicker();
  const groups = [
    { label: picker.messages.swatches, colors: picker.swatches },
    { label: picker.messages.recent, colors: picker.recent },
  ].filter((group) => group.colors.length > 0);
  if (groups.length === 0) return null;
  return (
    <div ref={ref} className={cn("grid gap-2", className)} {...props}>
      {groups.map((group) => (
        <div key={group.label} role="group" aria-label={group.label} className="grid gap-1.5">
          <span className="text-xs text-muted-foreground">{group.label}</span>
          <div className="flex flex-wrap gap-1.5">
            {group.colors.map((color) => {
              const chosen = !!picker.hex && picker.hex === color.hex && Math.round((picker.alpha ?? 1) * 100) === Math.round(color.alpha * 100);
              return (
                <button
                  key={`${color.hex}-${color.alpha}`}
                  type="button"
                  aria-label={picker.messages.swatch(color.hex, color.alpha)}
                  aria-pressed={chosen}
                  disabled={!picker.editable}
                  onClick={() => picker.commit({ hsv: hexToHsv(color.hex), alpha: color.alpha })}
                  className="size-5 overflow-hidden rounded-[4px] ring-1 ring-border outline-none ring-offset-1 ring-offset-popover focus-visible:ring-ring disabled:opacity-50 aria-pressed:ring-2 aria-pressed:ring-foreground"
                >
                  <ColorChip hex={color.hex} alpha={color.alpha} className="size-full" />
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
});

"use client";

import { Popover } from "@base-ui/react/popover";
import { type ChangeEvent, type ComponentPropsWithoutRef, type FocusEvent, type KeyboardEvent, forwardRef, useRef, useState } from "react";
import { clamp, hexToHsv, parseHex } from "./color-picker-color";
import { mergeRefs, useColorPicker } from "./color-picker-state";
import { cn } from "@/lib/utils";

/** A checkerboard under the colour, so opacity shows. */
export const checkerboard = "bg-[repeating-conic-gradient(#d4d4d4_0%_25%,#ffffff_0%_50%)] bg-[length:8px_8px]";

/** A colour chip over the checkerboard; the top half shows full opacity, the rest the real opacity. */
export function ColorChip({ hex, alpha, className }: { hex: string | null; alpha: number | null; className?: string }) {
  return (
    <span aria-hidden className={cn("relative block overflow-hidden", checkerboard, className)}>
      {hex && <span className="absolute inset-0" style={{ background: hex, opacity: alpha ?? 1 }} />}
      {/* Mixed shows a diagonal stroke instead of a colour. */}
      {!hex && <span className="absolute inset-0 bg-background bg-[linear-gradient(to_top_right,transparent_calc(50%-0.75px),var(--muted-foreground)_50%,transparent_calc(50%+0.75px))]" />}
    </span>
  );
}

/** The swatch that opens the picker. It shows the current colour, or a slash while mixed. */
export const ColorPickerTrigger = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button">>(function ColorPickerTrigger({ className, ...props }, ref) {
  const picker = useColorPicker();
  const valueText = picker.hex ? picker.messages.swatch(picker.hex, picker.alpha ?? 1) : picker.messages.mixed;
  return (
    <Popover.Trigger
      ref={mergeRefs(ref, picker.triggerRef)}
      disabled={picker.disabled}
      aria-label={`${picker.messages.open(picker.label)}, ${valueText}`}
      className={cn(
        "grid size-[calc(var(--uicoolkit-field-height,2.5rem)*0.6)] shrink-0 place-items-center overflow-hidden rounded-[5px] ring-1 ring-border outline-none focus-visible:ring-ring disabled:opacity-50 data-[popup-open]:ring-ring",
        className,
      )}
      {...props}
    >
      <ColorChip hex={picker.hex} alpha={picker.alpha} className="size-full" />
    </Popover.Trigger>
  );
});

type FieldOptions = {
  /** The text shown when not typing. */
  text: string;
  /** Applies typed text; returns an error message to reject it. */
  apply: (text: string) => string | null;
};

/** Typing commits on Enter or leaving the field and reverts on Escape; a rejected value stays to fix. */
function useTextField({ text, apply }: FieldOptions) {
  const picker = useColorPicker();
  const [draft, setDraftState] = useState<string | null>(null);
  // Mirrors the draft so the blur that follows Enter or Escape cannot apply it again.
  const draftRef = useRef<string | null>(null);
  const setDraft = (next: string | null) => {
    draftRef.current = next;
    setDraftState(next);
  };
  const submit = () => {
    const typed = draftRef.current;
    if (typed === null) return;
    if (typed === text) {
      setDraft(null);
      picker.setError(null);
      return;
    }
    const error = apply(typed);
    picker.setError(error);
    if (!error) setDraft(null);
  };
  return {
    value: draft ?? text,
    "aria-invalid": draft !== null && picker.error ? true : undefined,
    onFocus: (event: FocusEvent<HTMLInputElement>) => event.currentTarget.select(),
    onChange: (event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value),
    onBlur: submit,
    onKeyDown: (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Enter" && !event.nativeEvent.isComposing) {
        event.preventDefault();
        submit();
      } else if (event.key === "Escape" && draftRef.current !== null) {
        event.preventDefault();
        event.stopPropagation();
        setDraft(null);
        picker.setError(null);
      }
    },
  };
}

// No box of its own: the field around it shows focus, so typing never adds a filled rectangle.
export const inputBox =
  "h-7 min-w-0 rounded-sm bg-transparent px-1 text-sm tabular-nums outline-none placeholder:text-muted-foreground aria-invalid:text-destructive disabled:opacity-50";

/**
 * The field's box. Pressing anywhere in it except the swatch focuses the hex value and selects it,
 * so the whole field reads as one input; the swatch still opens the picker.
 */
export const ColorPickerField = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function ColorPickerField({ className, onMouseDown, ...props }, ref) {
  const picker = useColorPicker();
  return (
    <div
      ref={ref}
      data-slot="field"
      className={cn("flex min-w-0 items-center", !picker.disabled && "cursor-text", className)}
      onMouseDown={(event) => {
        onMouseDown?.(event);
        if (event.defaultPrevented || picker.disabled || (event.target as HTMLElement).closest("button, input")) return;
        // Keep focus from landing on the box itself, then hand it to the hex value.
        event.preventDefault();
        const input = document.getElementById(picker.inputId) as HTMLInputElement | null;
        input?.focus();
        input?.select();
      }}
      {...props}
    />
  );
});

/** The colour's name in the row, such as "Fill". It labels the hex input; clicking it focuses the input. */
export const ColorPickerLabel = forwardRef<HTMLLabelElement, ComponentPropsWithoutRef<"label">>(function ColorPickerLabel({ className, children, ...props }, ref) {
  const picker = useColorPicker();
  return (
    <label ref={ref} htmlFor={picker.inputId} className={cn("truncate text-xs text-muted-foreground select-none", className)} {...props}>
      {children ?? picker.label}
    </label>
  );
});

/** The colour as six hex digits after a fixed "#". Accepts three or six digits, with or without "#". */
export const ColorPickerHexInput = forwardRef<HTMLInputElement, ComponentPropsWithoutRef<"input">>(function ColorPickerHexInput({ className, id, ...props }, ref) {
  const picker = useColorPicker();
  const field = useTextField({
    text: picker.hex ? picker.hex.slice(1).toUpperCase() : "",
    apply: (typed) => {
      const hex = parseHex(typed);
      if (!hex) return picker.messages.invalidHex;
      picker.commit({ hsv: hexToHsv(hex), alpha: picker.alpha ?? 1 });
      return null;
    },
  });
  return (
    <span className={cn("flex min-w-0 items-center", className)}>
      {/* Shown, not typed: a pasted "#" is accepted too. */}
      {picker.hex && (
        <span aria-hidden className="text-sm text-muted-foreground select-none">
          #
        </span>
      )}
      <input
        ref={ref}
        id={id ?? picker.inputId}
        type="text"
        spellCheck={false}
        autoComplete="off"
        aria-label={`${picker.label} ${picker.messages.hex}`}
        aria-describedby={picker.error ? picker.errorId : undefined}
        placeholder={picker.messages.mixed}
        disabled={picker.disabled}
        readOnly={!picker.editable}
        maxLength={7}
        // Sized to its digits, so the "#" sits right against them wherever the input is placed.
        className={cn(inputBox, "min-w-[6ch] pl-0 uppercase [field-sizing:content]")}
        {...field}
        {...props}
      />
    </span>
  );
});

type NumberInputProps = Omit<ComponentPropsWithoutRef<"input">, "value" | "onChange" | "min" | "max"> & {
  /** The whole number shown, or null while mixed. */
  value: number | null;
  min: number;
  max: number;
  /** Applies a whole number inside the range. */
  onApply: (value: number) => void;
  /** Shown after the number, such as "%". */
  suffix?: string;
};

/** A whole-number channel, such as red or opacity. Arrow keys step by 1, with Shift by 10. */
export const ColorPickerNumberInput = forwardRef<HTMLInputElement, NumberInputProps>(function ColorPickerNumberInput(
  { value, min, max, onApply, suffix, className, onKeyDown, ...props },
  ref,
) {
  const picker = useColorPicker();
  const field = useTextField({
    text: value === null ? "" : String(value),
    apply: (typed) => {
      const number = Number(typed.trim().replace(/%$/, ""));
      if (typed.trim() === "" || !Number.isFinite(number) || number < min || number > max) return picker.messages.range(min, max);
      onApply(Math.round(number));
      return null;
    },
  });
  return (
    <span className={cn("flex min-w-0 items-center", className)}>
      <input
        ref={ref}
        type="text"
        inputMode="numeric"
        autoComplete="off"
        aria-describedby={picker.error ? picker.errorId : undefined}
        placeholder={value === null ? picker.messages.mixed : undefined}
        disabled={picker.disabled}
        readOnly={!picker.editable}
        className={cn(inputBox, "w-full text-right")}
        {...field}
        {...props}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          field.onKeyDown(event);
          if (event.defaultPrevented || !picker.editable || (event.key !== "ArrowUp" && event.key !== "ArrowDown")) return;
          event.preventDefault();
          const step = (event.shiftKey ? 10 : 1) * (event.key === "ArrowUp" ? 1 : -1);
          onApply(clamp((value ?? min) + step, min, max));
        }}
      />
      {suffix && <span aria-hidden className="pl-0.5 text-xs text-muted-foreground">{suffix}</span>}
    </span>
  );
});

/** Opacity as a percentage, beside the hex value in the row and in the picker. */
export const ColorPickerAlphaInput = forwardRef<HTMLInputElement, Omit<ComponentPropsWithoutRef<"input">, "value" | "onChange" | "min" | "max">>(function ColorPickerAlphaInput({ className, ...props }, ref) {
  const picker = useColorPicker();
  return (
    <ColorPickerNumberInput
      ref={ref}
      aria-label={`${picker.label} ${picker.messages.opacity}`}
      value={picker.alpha === null ? null : Math.round(picker.alpha * 100)}
      min={0}
      max={100}
      suffix="%"
      onApply={(percent) => picker.commit({ hsv: picker.fallback.hsv, alpha: percent / 100 })}
      className={cn("w-12", className)}
      {...props}
    />
  );
});

/** Why a typed value was rejected. It stays in the field to fix. */
export const ColorPickerError = forwardRef<HTMLParagraphElement, ComponentPropsWithoutRef<"p">>(function ColorPickerError({ className, ...props }, ref) {
  const { error, errorId } = useColorPicker();
  if (!error) return null;
  return <p ref={ref} id={errorId} role="alert" className={cn("basis-full pt-1 text-xs text-destructive", className)} {...props}>{error}</p>;
});

"use client";

import { Popover } from "@base-ui/react/popover";
import { forwardRef, useId, useRef, useState } from "react";
import { type ColorValue, type Hsv, hexToHsv, hsvToHex, parseHex, sameColor } from "./color-picker-color";
import { type ColorPickerContextValue, type ColorPickerFormat, type ColorPickerProps, ColorPickerContext, defaultMessages, mergeRefs } from "./color-picker-state";
import { cn } from "@/lib/utils";

type Local = { hsv: Hsv; alpha: number };

const fromValue = (value: ColorValue | null): Local | null => (value ? { hsv: hexToHsv(value.hex), alpha: value.alpha } : null);
const toValue = (local: Local): ColorValue => ({ hex: hsvToHex(local.hsv), alpha: Math.round(local.alpha * 100) / 100 });
const toSwatch = (swatch: string | ColorValue): ColorValue | null => {
  if (typeof swatch !== "string") return { hex: parseHex(swatch.hex) ?? swatch.hex, alpha: swatch.alpha };
  const hex = parseHex(swatch);
  return hex ? { hex, alpha: 1 } : null;
};

/**
 * A colour your app owns, edited from a fill-style row: the swatch opens a picker with an area,
 * hue and opacity sliders, Hex/RGB/HSL entry, an eyedropper and swatches. Drags preview live and
 * commit once on release.
 */
export const ColorPicker = forwardRef<HTMLDivElement, ColorPickerProps>(function ColorPicker(
  {
    label,
    value,
    onValueCommit,
    onValueChange,
    swatches = [],
    recent: recentProp,
    onRecentChange,
    recentLimit = 8,
    format: formatProp,
    defaultFormat = "hex",
    defaultOpen = false,
    onFormatChange,
    disabled = false,
    readOnly = false,
    motion = true,
    container,
    messages: messagesProp,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const id = useId();
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [open, setOpenState] = useState(defaultOpen && !disabled);
  const [error, setError] = useState<string | null>(null);
  const [formatState, setFormatState] = useState<ColorPickerFormat>(defaultFormat);
  const [recentState, setRecentState] = useState<ColorValue[]>([]);
  // The colour being shown. It keeps its own hue, so dragging through grey or black does not lose it.
  const [local, setLocal] = useState<Local | null>(() => fromValue(value));
  const [seen, setSeen] = useState(value);
  // The last previewed colour, so a release commits exactly what was shown.
  const latest = useRef<Local | null>(local);
  const dragging = useRef(false);

  if (!sameColor(seen, value)) {
    setSeen(value);
    const keepsHue = value && local && sameColor(toValue(local), value);
    if (!dragging.current && !keepsHue) setLocal(fromValue(value));
  }

  const format = formatProp ?? formatState;
  const recent = recentProp ?? recentState;
  const editable = !disabled && !readOnly;
  const show = (next: Local) => {
    latest.current = next;
    setLocal(next);
  };

  const commit = (next: Local) => {
    dragging.current = false;
    show(next);
    const color = toValue(next);
    if (sameColor(color, value)) return;
    onValueCommit(color);
    const nextRecent = [color, ...recent.filter((item) => !sameColor(item, color))].slice(0, recentLimit);
    if (recentProp === undefined) setRecentState(nextRecent);
    onRecentChange?.(nextRecent);
  };

  const context: ColorPickerContextValue = {
    label,
    color: local,
    hex: local ? hsvToHex(local.hsv) : null,
    alpha: local ? local.alpha : null,
    preview: (next) => {
      if (!editable) return;
      dragging.current = true;
      show(next);
      onValueChange?.(toValue(next));
    },
    commit: (next) => editable && commit(next),
    release: () => {
      if (dragging.current && latest.current) commit(latest.current);
      dragging.current = false;
    },
    fallback: local ?? { hsv: { h: 0, s: 0, v: 1 }, alpha: 1 },
    format,
    setFormat: (next) => {
      if (formatProp === undefined) setFormatState(next);
      onFormatChange?.(next);
    },
    swatches: swatches.map(toSwatch).filter((swatch): swatch is ColorValue => swatch !== null),
    recent,
    open,
    setOpen: (next) => setOpenState(next && !disabled),
    error,
    setError,
    errorId: `${id}-error`,
    inputId: `${id}-input`,
    disabled,
    readOnly,
    editable,
    animated: motion,
    container,
    messages,
    triggerRef,
    rootRef,
  };

  return (
    <ColorPickerContext.Provider value={context}>
      <Popover.Root open={open} onOpenChange={(next) => context.setOpen(next)}>
        <div
          ref={mergeRefs(ref, rootRef)}
          role="group"
          aria-label={label}
          data-mixed={value === null || undefined}
          data-disabled={disabled || undefined}
          data-readonly={readOnly || undefined}
          data-invalid={error ? true : undefined}
          className={cn("group/color flex min-w-0 flex-wrap items-center", className)}
          {...props}
        >
          {children}
        </div>
      </Popover.Root>
    </ColorPickerContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type MutableRefObject, type ReactNode, type Ref, createContext, useContext } from "react";
import type { ColorValue, Hsv } from "./color-picker-color";

export type ColorPickerFormat = "hex" | "rgb" | "hsl";

/** Replaceable text, for example to translate. */
export type ColorPickerMessages = {
  mixed: string;
  open: (label: string) => string;
  area: string;
  areaValue: (saturation: number, brightness: number) => string;
  hue: string;
  opacity: string;
  formats: Record<ColorPickerFormat, string>;
  format: string;
  hex: string;
  channels: { r: string; g: string; b: string; h: string; s: string; l: string };
  eyedropper: string;
  swatches: string;
  recent: string;
  swatch: (hex: string, alpha: number) => string;
  invalidHex: string;
  range: (min: number, max: number) => string;
};

export const defaultMessages: ColorPickerMessages = {
  mixed: "Mixed",
  open: (label) => `Edit ${label}`,
  area: "Saturation and brightness",
  areaValue: (saturation, brightness) => `Saturation ${saturation}%, brightness ${brightness}%`,
  hue: "Hue",
  opacity: "Opacity",
  formats: { hex: "Hex", rgb: "RGB", hsl: "HSL" },
  format: "Colour format",
  hex: "Hex",
  channels: { r: "Red", g: "Green", b: "Blue", h: "Hue", s: "Saturation", l: "Lightness" },
  eyedropper: "Pick a colour from the screen",
  swatches: "Swatches",
  recent: "Recent",
  swatch: (hex, alpha) => `${hex.toUpperCase()}${alpha < 1 ? `, ${Math.round(alpha * 100)}% opacity` : ""}`,
  invalidHex: "Enter a hex colour such as FF5B1F.",
  range: (min, max) => `Enter ${min} to ${max}.`,
};

export type ColorPickerProps = Omit<ComponentPropsWithoutRef<"div">, "defaultValue" | "onChange"> & {
  /** Names the colour, such as "Fill". Labels the swatch, inputs and picker. */
  label: string;
  /** The committed colour; null when a selection holds different colours. Your app owns it. */
  value: ColorValue | null;
  /** Called once per finished change: a released drag, a typed value, a swatch or the eyedropper. */
  onValueCommit: (value: ColorValue) => void;
  /** Live values while dragging the area or a slider, for previewing before the commit. */
  onValueChange?: (value: ColorValue) => void;
  /** Colours your app offers, such as the document's colours. Hex strings or colours with opacity. */
  swatches?: (string | ColorValue)[];
  /** The last colours chosen, newest first. Pass with onRecentChange to store them; otherwise the picker keeps them. */
  recent?: ColorValue[];
  onRecentChange?: (recent: ColorValue[]) => void;
  /** How many recent colours to keep. */
  recentLimit?: number;
  /** The format the value inputs show. */
  format?: ColorPickerFormat;
  defaultFormat?: ColorPickerFormat;
  onFormatChange?: (format: ColorPickerFormat) => void;
  disabled?: boolean;
  readOnly?: boolean;
  /** Opens the picker when it first renders, such as right after a fill becomes a colour. */
  defaultOpen?: boolean;
  /** Popover and slider transitions. Reduced motion is always honored. */
  motion?: boolean;
  /** Where the picker is portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  messages?: Partial<ColorPickerMessages>;
};

export type ColorPickerContextValue = {
  label: string;
  /** The colour shown, live while dragging; null while mixed and untouched. */
  color: { hsv: Hsv; alpha: number } | null;
  hex: string | null;
  alpha: number | null;
  preview: (next: { hsv: Hsv; alpha: number }) => void;
  commit: (next: { hsv: Hsv; alpha: number }) => void;
  /** Ends a drag: commits what was previewed. */
  release: () => void;
  /** Where a mixed colour starts when someone begins editing it. */
  fallback: { hsv: Hsv; alpha: number };
  format: ColorPickerFormat;
  setFormat: (format: ColorPickerFormat) => void;
  swatches: ColorValue[];
  recent: ColorValue[];
  open: boolean;
  setOpen: (open: boolean) => void;
  error: string | null;
  setError: (error: string | null) => void;
  errorId: string;
  inputId: string;
  disabled: boolean;
  readOnly: boolean;
  editable: boolean;
  animated: boolean;
  container?: HTMLElement | null;
  messages: ColorPickerMessages;
  triggerRef: MutableRefObject<HTMLButtonElement | null>;
  /** The row, which the picker opens against so it never covers it. */
  rootRef: MutableRefObject<HTMLDivElement | null>;
};

export const ColorPickerContext = createContext<ColorPickerContextValue | null>(null);

/** State of the nearest ColorPicker, for building custom parts. */
export function useColorPicker() {
  const context = useContext(ColorPickerContext);
  if (!context) throw new Error("ColorPicker parts must be rendered inside <ColorPicker>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

export type ColorPickerChildren = { children?: ReactNode };

